#!/usr/bin/env bash
set -euo pipefail

HOME_DIR="$HOME"
RELAY_DIR="$HOME_DIR/.cre-relay"
AUTOPILOT_DIR="$RELAY_DIR/autopilot"
AUTOPILOT_PY="$RELAY_DIR/autopilot.py"
AUTOPILOT_CTL="$RELAY_DIR/autopilotctl"
HS_CONFIG="$HOME_DIR/.hammerspoon/init.lua"
STAMP="$(date +%Y%m%d-%H%M%S)"

fail() {
  printf '
STOP: %s
' "$*" >&2
  exit 1
}

[[ -f "$RELAY_DIR/bridge.py" ]] || fail "Missing relay bridge: $RELAY_DIR/bridge.py"
[[ -f "$RELAY_DIR/runner.py" ]] || fail "Missing relay runner: $RELAY_DIR/runner.py"
[[ -f "$HS_CONFIG" ]] || fail "Missing Hammerspoon config: $HS_CONFIG"
[[ -x /opt/anaconda3/bin/python3 ]] || fail "Missing /opt/anaconda3/bin/python3"

mkdir -p "$AUTOPILOT_DIR/runs"

if [[ -x "$AUTOPILOT_CTL" ]]; then
  "$AUTOPILOT_CTL" stop >/dev/null 2>&1 || true
  sleep 1
fi

cp -p "$HS_CONFIG" "$HS_CONFIG.backup-autopilot-v6-$STAMP"

printf '%s' '' | /usr/bin/base64 -D > "$AUTOPILOT_PY"
printf '%s' '' | /usr/bin/base64 -D > "$AUTOPILOT_CTL"
chmod 700 "$AUTOPILOT_PY" "$AUTOPILOT_CTL"

HS_SECTION_FILE="$AUTOPILOT_DIR/hs_v6_section.lua"
printf '%s' '' | /usr/bin/base64 -D > "$HS_SECTION_FILE"

python3 - "$HS_CONFIG" "$HS_SECTION_FILE" <<'PATCH_HS_PY'
from pathlib import Path
import sys

path = Path(sys.argv[1])
section_path = Path(sys.argv[2])
text = path.read_text(encoding='utf-8')

for marker in (
    '-- === CRE RELAY V4 AUTO LOOP ===',
    '-- === CRE RELAY V5 AUTO LOOP ===',
    '-- === CRE AUTOPILOT V6 DAEMON CONTROL ===',
):
    if marker in text:
        text = text.split(marker, 1)[0].rstrip() + '\n'

section = section_path.read_text(encoding='utf-8')
path.write_text(text.rstrip() + '\n\n' + section.lstrip(), encoding='utf-8')
print('Hammerspoon V6 control installed.')
PATCH_HS_PY

printf '
=== PYTHON SYNTAX CHECK ===
'
/opt/anaconda3/bin/python3 -m py_compile "$AUTOPILOT_PY"

printf '
=== AUTOPILOT + BRIDGE SELF-TEST ===
'
"$AUTOPILOT_CTL" self-test

printf '
=== RESTART HAMMERSPOON ===
'
killall Hammerspoon >/dev/null 2>&1 || true
sleep 1
open -a Hammerspoon
sleep 2

printf '
=== START UNATTENDED SECURITY-001 AUTOPILOT ===
'
"$AUTOPILOT_CTL" start

printf '
=== STATUS ===
'
"$AUTOPILOT_CTL" status || true

cat <<'DONE_EOF'

CRE AUTOPILOT V6 INSTALLED AND STARTED

The daemon now owns the loop:
controller reply -> validate/normalize -> safe container bridge -> result -> controller -> repeat.

It automatically resolves HUMAN_REQUIRED, malformed protocol, missing prior results,
duplicate actions, browser delays, send retries, Docker/Colima recovery, and low-battery pauses.

It stops only on MISSION_COMPLETE or when you run:
  ~/.cre-relay/autopilotctl stop

Status:
  ~/.cre-relay/autopilotctl status

Logs:
  ~/.cre-relay/autopilotctl logs 200

Hammerspoon:
  Control+Option+Command+A  start/stop
  Control+Option+Command+P  status
DONE_EOF
